create table if not exists public.platform_restore_requests(id uuid primary key default gen_random_uuid(),backup_name text not null,reason text not null check(length(trim(reason)) between 20 and 1000),scope text not null default 'full' check(scope in('full','clinic','table')),scope_ref text,status text not null default 'requested' check(status in('requested','approved','rejected','executing','completed','failed','canceled')),requested_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),requested_at timestamptz not null default now(),decided_at timestamptz,executed_at timestamptz,result jsonb);
alter table public.platform_restore_requests enable row level security;create policy "plataforma consulta restauracoes" on public.platform_restore_requests for select to authenticated using(public.is_platform_admin());
create or replace function public.platform_request_restore(p_backup_name text,p_reason text,p_scope text default 'full',p_scope_ref text default null) returns uuid language plpgsql security definer set search_path=public,storage as $$ declare v_id uuid;begin if not is_platform_admin() then raise exception 'Acesso restrito';end if;if length(trim(p_reason))<20 then raise exception 'Justificativa insuficiente';end if;if p_scope not in('full','clinic','table') then raise exception 'Escopo inválido';end if;if not exists(select 1 from storage.objects where bucket_id='backups' and name=p_backup_name)then raise exception 'Backup não encontrado';end if;insert into platform_restore_requests(backup_name,reason,scope,scope_ref,requested_by)values(p_backup_name,trim(p_reason),p_scope,p_scope_ref,auth.uid())returning id into v_id;insert into audit_log(user_id,action,collection,record_id,changes)values(auth.uid(),'create','platform_restore_requests',v_id::text,jsonb_build_object('backup',p_backup_name,'scope',p_scope));return v_id;end;$$;
create or replace function public.platform_decide_restore(p_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path=public as $$ declare r platform_restore_requests;begin if not is_platform_admin()then raise exception 'Acesso restrito';end if;select*into r from platform_restore_requests where id=p_id for update;if r.id is null or r.status<>'requested'then raise exception 'Solicitação indisponível';end if;if r.requested_by=auth.uid()then raise exception 'Aprovação exige outro administrador';end if;update platform_restore_requests set status=case when p_approve then'approved'else'rejected'end,approved_by=auth.uid(),decided_at=now()where id=p_id;insert into audit_log(user_id,action,collection,record_id,changes)values(auth.uid(),'update','platform_restore_requests',p_id::text,jsonb_build_object('approved',p_approve));end;$$;
revoke all on function public.platform_request_restore(text,text,text,text),public.platform_decide_restore(uuid,boolean) from public,anon;grant execute on function public.platform_request_restore(text,text,text,text),public.platform_decide_restore(uuid,boolean) to authenticated;
